'use strict';

const SEARCH_ENDPOINT = 'https://itunes.apple.com/search';
const LOOKUP_ENDPOINT = 'https://itunes.apple.com/lookup';
const TOP_ENDPOINT = 'https://rss.marketingtools.apple.com/api/v2/cn/podcasts/top/100/podcasts.json';
const COUNTRY = 'cn';
const SEARCH_LIMIT = 200;
const PAGE_SIZE = 40;
const CATALOG_LIMIT = 200;
const CACHE_MS = 10 * 60 * 1000;

const EXPLORE_CATEGORIES = [
  { key: 'top', title: '热门节目' },
  { key: 'news', title: '新闻' },
  { key: 'business', title: '商务' },
  { key: 'culture', title: '社会与文化' },
  { key: 'education', title: '教育' },
  { key: 'technology', title: '科技' }
];

function text(value) {
  return value === undefined || value === null ? '' : String(value).trim();
}

function integer(value, fallback) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? Math.trunc(parsed) : fallback;
}

function boundedPage(value) {
  return Math.max(1, Math.min(5, integer(value, 1)));
}

function appleBookKey(id) {
  return `apple:podcast:${text(id)}`;
}

function appleEpisodeKey(id) {
  return `apple:podcast:episode:${text(id)}`;
}

function idFromValue(value) {
  const raw = text(value);
  const keyMatch = raw.match(/apple:podcast:(?:episode:)?(\d+)/i);
  if (keyMatch) return keyMatch[1];
  const urlMatch = raw.match(/\/id(\d+)/i);
  if (urlMatch) return urlMatch[1];
  return /^\d+$/.test(raw) ? raw : '';
}

function isHttpUrl(value) {
  return /^https?:\/\//i.test(text(value));
}

function largeArtwork(value) {
  const url = text(value);
  return url
    .replace(/\/\d+x\d+bb\.(jpg|jpeg|png)(?:\?.*)?$/i, '/600x600bb.$1')
    .replace(/\/\d+x\d+bb\.(jpg|jpeg|png)$/i, '/600x600bb.$1');
}

function genreNames(value) {
  if (!Array.isArray(value)) return '';
  return value.map(item => typeof item === 'string' ? item : text(item && item.name))
    .filter(Boolean).join(' · ');
}

function dateLabel(value) {
  const raw = text(value);
  if (!raw) return '';
  const date = new Date(raw);
  if (!Number.isFinite(date.getTime())) return '';
  const year = date.getUTCFullYear();
  const month = String(date.getUTCMonth() + 1).padStart(2, '0');
  const day = String(date.getUTCDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

function joinIntro(parts) {
  return parts.map(text).filter(Boolean).join('\n');
}

function requestHeaders() {
  return {
    Accept: 'application/json',
    'Accept-Language': 'zh-CN,zh;q=0.9,en;q=0.7'
  };
}

async function fetchJson(url) {
  const response = await reader.http.fetch({
    url,
    method: 'GET',
    headers: requestHeaders(),
    timeoutMs: 30000
  });
  const status = integer(response && response.status, 0);
  if (status < 200 || status >= 300) throw new Error(`Apple 接口请求失败：HTTP ${status || 'unknown'}`);
  try {
    return JSON.parse(text(response && response.body));
  } catch (_error) {
    throw new Error('Apple 接口返回了无法识别的数据');
  }
}

async function cachedJson(key, loader) {
  try {
    const cached = await reader.storage.get(key);
    if (cached && typeof cached === 'object' &&
        integer(cached.savedAt, 0) + CACHE_MS > Date.now() && cached.value !== undefined) {
      return cached.value;
    }
  } catch (_error) {}
  const value = await loader();
  try {
    await reader.storage.set(key, { savedAt: Date.now(), value });
  } catch (_error) {}
  return value;
}

function podcastSummary(item) {
  const id = text(item && (item.collectionId || item.trackId || item.id));
  if (!id) return null;
  const title = text(item.collectionName || item.trackName || item.name);
  if (!title) return null;
  const author = text(item.artistName);
  const genres = genreNames(item.genres);
  const episodeCount = integer(item.trackCount, 0);
  const intro = joinIntro([
    genres,
    episodeCount > 0 ? `约 ${episodeCount} 集` : '',
    dateLabel(item.releaseDate) ? `更新于 ${dateLabel(item.releaseDate)}` : ''
  ]);
  return {
    bookKey: appleBookKey(id),
    title,
    author,
    coverUrl: largeArtwork(item.artworkUrl600 || item.artworkUrl100),
    intro,
    bookUrl: text(item.collectionViewUrl || item.trackViewUrl || item.url) ||
      `https://podcasts.apple.com/cn/podcast/id${id}`,
    tocUrl: `${LOOKUP_ENDPOINT}?id=${encodeURIComponent(id)}&entity=podcastEpisode&country=${COUNTRY}&limit=${CATALOG_LIMIT}`,
    mediaType: 'audiobook'
  };
}

function chartSummary(item) {
  const id = text(item && item.id);
  if (!id) return null;
  return {
    bookKey: appleBookKey(id),
    title: text(item.name),
    author: text(item.artistName),
    coverUrl: largeArtwork(item.artworkUrl100),
    intro: genreNames(item.genres),
    bookUrl: text(item.url) || `https://podcasts.apple.com/cn/podcast/id${id}`,
    tocUrl: `${LOOKUP_ENDPOINT}?id=${encodeURIComponent(id)}&entity=podcastEpisode&country=${COUNTRY}&limit=${CATALOG_LIMIT}`,
    mediaType: 'audiobook'
  };
}

function lookupUrl(id, entity, limit) {
  const params = [
    `id=${encodeURIComponent(id)}`,
    `country=${COUNTRY}`
  ];
  if (entity) params.push(`entity=${encodeURIComponent(entity)}`);
  if (limit) params.push(`limit=${encodeURIComponent(limit)}`);
  return `${LOOKUP_ENDPOINT}?${params.join('&')}`;
}

async function search(input) {
  const keyword = text(input && input.keyword);
  if (!keyword) return [];
  const page = boundedPage(input && input.page);
  const cacheKey = `apple-podcasts:search:${keyword.toLowerCase()}`;
  const payload = await cachedJson(cacheKey, () => fetchJson(
    `${SEARCH_ENDPOINT}?term=${encodeURIComponent(keyword)}&media=podcast&entity=podcast` +
    `&country=${COUNTRY}&limit=${SEARCH_LIMIT}&explicit=Yes`
  ));
  const results = Array.isArray(payload && payload.results) ? payload.results : [];
  const start = (page - 1) * PAGE_SIZE;
  return results.slice(start, start + PAGE_SIZE).map(podcastSummary).filter(Boolean);
}

async function detail(input) {
  const id = idFromValue(input && (input.bookKey || input.bookUrl));
  if (!id) throw new Error('缺少有效的 Apple Podcasts 节目 ID');
  const payload = await cachedJson(`apple-podcasts:detail:${id}`, () =>
    fetchJson(lookupUrl(id, 'podcast', 1)));
  const results = Array.isArray(payload && payload.results) ? payload.results : [];
  const item = results.find(value => value && value.kind === 'podcast') || results[0];
  const summary = podcastSummary(item || { collectionId: id });
  if (!summary || !summary.title) throw new Error('没有找到这个 Apple Podcasts 节目');
  return {
    ...summary,
    chapterCount: Math.max(0, integer(item && item.trackCount, 0)),
    intro: joinIntro([
      genreNames(item && item.genres),
      item && item.contentAdvisoryRating === 'Explicit' ? '包含成人内容标记' : '',
      dateLabel(item && item.releaseDate) ? `最近更新：${dateLabel(item.releaseDate)}` : '',
      '单集目录由 Apple Podcasts 提供，最多显示最近 200 集。'
    ])
  };
}

function episodeToChapter(item, ordinal) {
  const episodeId = text(item && item.trackId);
  const mediaUrl = text(item && (item.episodeUrl || item.previewUrl));
  if (!episodeId || !mediaUrl || !isHttpUrl(mediaUrl)) return null;
  return {
    chapterKey: appleEpisodeKey(episodeId),
    title: text(item.trackName) || `第 ${ordinal + 1} 集`,
    ordinal,
    chapterUrl: mediaUrl,
    mediaType: 'audiobook'
  };
}

async function catalog(input) {
  const id = idFromValue(input && (input.bookKey || input.bookUrl || input.tocUrl));
  if (!id) throw new Error('缺少有效的 Apple Podcasts 节目 ID');
  const forceRefresh = input && input.forceRefresh === true;
  const loader = () => fetchJson(lookupUrl(id, 'podcastEpisode', CATALOG_LIMIT));
  const payload = forceRefresh ? await loader() :
    await cachedJson(`apple-podcasts:catalog:${id}`, loader);
  const results = Array.isArray(payload && payload.results) ? payload.results : [];
  return results.filter(item => item &&
      (item.wrapperType === 'podcastEpisode' || item.kind === 'podcast-episode'))
    .map(episodeToChapter).filter(Boolean);
}

async function content(input) {
  let mediaUrl = text(input && input.chapterUrl);
  const episodeId = idFromValue(input && input.chapterKey);
  let episode = null;
  if (!isHttpUrl(mediaUrl) && episodeId) {
    const payload = await fetchJson(lookupUrl(episodeId, 'podcastEpisode', 1));
    const results = Array.isArray(payload && payload.results) ? payload.results : [];
    episode = results.find(item => item &&
      (item.wrapperType === 'podcastEpisode' || item.kind === 'podcast-episode')) || results[0];
    mediaUrl = text(episode && (episode.episodeUrl || episode.previewUrl));
  }
  if (!isHttpUrl(mediaUrl)) throw new Error('这一集没有可播放的公开音频地址');
  return {
    contentType: 'audio',
    content: '',
    mediaUrl,
    mediaUrls: [mediaUrl],
    mediaHeaders: {
      'User-Agent': 'Mozilla/5.0 (Linux; HarmonyOS) AppleWebKit/537.36 Mobile Safari/537.36',
      Referer: 'https://podcasts.apple.com/'
    },
    title: text(input && input.title) || text(episode && episode.trackName),
    message: ''
  };
}

async function exploreMenu() {
  return EXPLORE_CATEGORIES.map(item => ({ ...item }));
}

async function explore(input) {
  const category = text(input && input.category) || 'top';
  const page = boundedPage(input && input.page);
  if (category === 'top') {
    const payload = await cachedJson('apple-podcasts:top:cn', () => fetchJson(TOP_ENDPOINT));
    const results = Array.isArray(payload && payload.feed && payload.feed.results) ?
      payload.feed.results : [];
    const start = (page - 1) * PAGE_SIZE;
    return results.slice(start, start + PAGE_SIZE).map(chartSummary).filter(Boolean);
  }
  const terms = {
    news: '新闻',
    business: '商务',
    culture: '社会与文化',
    education: '教育',
    technology: '科技'
  };
  return search({ keyword: terms[category] || category, page });
}

module.exports = { search, exploreMenu, explore, detail, catalog, content };
